def transform(grid):
    out = copy_grid(grid)
    rows = len(out)
    if rows == 0:
        return out
    cols = len(out[0])
    # Find all 9s
    nine_positions = []
    for r in range(rows):
        for c in range(cols):
            if out[r][c] == 9:
                nine_positions.append((r, c))
    if len(nine_positions) == 0:
        return out
    # Find bounding box of 9s
    min_r = rows
    max_r = -1
    min_c = cols
    max_c = -1
    for (r, c) in nine_positions:
        if r < min_r: min_r = r
        if r > max_r: max_r = r
        if c < min_c: min_c = c
        if c > max_c: max_c = c
    # Get the 4-region (all 4s adjacent to 9s or in the 9 block)
    # Instead, use component with background=9 to get 4 components
    comps = components(out, 9, 4)
    # Only consider 4 components that touch the border of the grid
    border_4_comps = []
    for comp in comps:
        for pixel in comp:
            r, c, col = pixel
            if col != 4:
                continue
            if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                border_4_comps.append(comp)
                break
    # For each border 4 component, set all its 4 pixels to 1
    for comp in border_4_comps:
        for pixel in comp:
            r, c, col = pixel
            if col == 4:
                out[r][c] = 1
    return out

