def components(g, background, connectivity):
    # connectivity is 4 or 8
    rows = len(g)
    cols = len(g[0]) if rows > 0 else 0
    visited = [[False] * cols for _ in range(rows)]
    result = []

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and g[r][c] == background:
                # BFS for connectivity
                stack = [(r, c)]
                visited[r][c] = True
                comp = []
                while len(stack) > 0:
                    cr, cc = stack.pop()
                    comp.append([cr, cc, background])
                    if connectivity == 4:
                        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and g[nr][nc] == background:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                    else:  # connectivity == 8
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = cr + dr, cc + dc
                                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and g[nr][nc] == background:
                                    visited[nr][nc] = True
                                    stack.append((nr, nc))
                result.append(comp)
    return result

