def transform(grid):
    # Find background component (color that appears at least once on border or most common non-foreground)
    # Use border-based background detection
    rows = len(grid)
    if rows == 0:
        return copy_grid(grid)
    cols = len(grid[0])

    # Collect border colors
    border_colors = []
    for r in range(rows):
        if r == 0 or r == rows - 1:
            for c in range(cols):
                border_colors.append(grid[r][c])
        else:
            border_colors.append(grid[r][0])
            border_colors.append(grid[r][cols - 1])

    # Count border color frequencies
    border_counts = {}
    for col in border_colors:
        if col in border_counts:
            border_counts[col] = border_counts[col] + 1
        else:
            border_counts[col] = 1

    # Choose background as the most frequent border color
    # If multiple, pick smallest color (lowest value)
    max_count = -1
    bg = None
    for col, cnt in border_counts.items():
        if cnt > max_count or (cnt == max_count and col < bg):
            max_count = cnt
            bg = col

    # If no border (single cell), use grid[0][0]
    if bg is None:
        bg = grid[0][0]

    # Find all components of background
    comps = components(grid, bg, 4)

    # Collect all non-background colors that appear in components (foreground)
    fg_colors = []
    for comp in comps:
        # comp is list of [r,c,color] where color == bg
        # We don't need to extract fg from comps; instead collect all colors != bg
        pass

    # Find all colors present in grid that are not background
    all_colors = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                all_colors.append(grid[r][c])

    # If no foreground, return grid unchanged
    if len(all_colors) == 0:
        return copy_grid(grid)

    # Count foreground color frequencies (excluding background)
    fg_counts = {}
    for col in all_colors:
        if col in fg_counts:
            fg_counts[col] = fg_counts[col] + 1
        else:
            fg_counts[col] = 1

    # Choose foreground color with highest frequency; if tie, smallest color
    max_fg = -1
    fg = None
    for col, cnt in fg_counts.items():
        if cnt > max_fg or (cnt == max_fg and col < fg):
            max_fg = cnt
            fg = col

    # Replace all foreground colors with fg (but we need to replace with a single color 1 for demo pattern)
    # Based on demonstrations: replace all foreground (non-background) with 1 in a connected region around the background?
    # From demo 1: input has 4s and 9; output has 1s around 9 but not all 4s -> only the component adjacent to 9 gets 1?
    # From demo 2: input has 7s and 8; output has 1s forming a ring around 8, not all 7s.

    # So we need to find components of non-background that are adjacent to background, and replace only those with 1.
    # But demo 1: 9 is background? No: background is 4 (border), 9 is inside; output has 1s around 9 but not all 4s.
    # In demo 1: input border is 4, center has 9; output has 1s in a cross around 9 and bottom row 1s.
    # In demo 2: input border 7, center 8; output has 1s in a ring around 8 and bottom row 1s.

    # Thus: replace all pixels that are in components of non-background that touch the background component.

    # Find background component pixels (all bg pixels)
    bg_pixels = []
    for comp in comps:
        for p in comp:
            bg_pixels.append(p)

    # Collect all non-background pixels that are adjacent to any bg pixel
    to_replace = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                # check 4-connectivity to any bg pixel
                found = False
                for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == bg:
                        found = True
                        break
                if found:
                    to_replace.append([r, c])

    # If no to_replace, return grid
    if len(to_replace) == 0:
        return copy_grid(grid)

    # Create output grid as copy
    out = copy_grid(grid)

    # Replace all to_replace pixels with 1
    for p in to_replace:
        r, c = p[0], p[1]
        out[r][c] = 1

    # Additionally, for demo 1 and 2, the bottom row also gets 1s under the foreground area?
    # In demo 1: row 7 (last row) has 1s from col 0 to 6, even though row 7 may not touch bg directly? 
    # But row 7 touches row 6 which touches bg component (since 9 is at row 3 col 2, row 6 col 2 is 4, so row 7 col 2 is adjacent to row 6 col 2 which is bg), so it is included.
    # Similarly demo 2: row 4 (last row) has 1s in cols 0-1 and 4-4? output row4: [1,1,1,7,7] -> cols 0-2 are 1, row4 col3-4 are 7, but row3 col2 is 7 (bg), row4 col1-2 are 7 in input, but output row4 col0-2 are 1 because adjacent to row3 col1-2 (bg 7) at row3.
