def components(g, background, connectivity):
    rows = len(g)
    if rows == 0:
        return []
    cols = len(g[0])
    visited = [[False] * cols for _ in range(rows)]
    out = []
    for r in range(rows):
        for c in range(cols):
            if visited[r][c] or g[r][c] == background:
                continue
            stack = [(r, c)]
            visited[r][c] = True
            comp = []
            while stack:
                cr, cc = stack.pop()
                comp.append([cr, cc, g[cr][cc]])
                if connectivity == 4:
                    for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and g[nr][nc] == g[cr][cc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                else:  # connectivity == 8
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and g[nr][nc] == g[cr][cc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
            out.append(comp)
    return out

