def transform(grid):
    out = copy_grid(grid)
    # Find the row index of the first row that contains 4
    first4 = None
    for r in range(len(out)):
        has4 = False
        for c in range(len(out[0])):
            if out[r][c] == 4:
                has4 = True
                break
        if has4 and first4 is None:
            first4 = r
    # Find the row index of the last row that contains 4
    last4 = None
    for r in range(len(out) - 1, -1, -1):
        has4 = False
        for c in range(len(out[0])):
            if out[r][c] == 4:
                has4 = True
                break
        if has4:
            last4 = r
            break
    if first4 is None or last4 is None:
        return out
    # Collect all rows that are not all 4 and not above first4
    # We want to copy the pattern from rows just below first4 up to last4-1, and place it starting at row last4+1
    # But avoid overlapping with the 4 band
    pattern_rows = []
    for r in range(first4, last4 + 1):
        # Skip rows that are all 4s? But row first4 may be all 4s if band starts at first4
        all_four = True
        for c in range(len(out[0])):
            if out[r][c] != 4:
                all_four = False
                break
        if not all_four:
            pattern_rows.append(out[r][:])  # copy row
    # Determine how many pattern rows to copy (all non-4 rows within [first4, last4])
    # Place them below the 4 band
    insert_start = last4 + 1
    if len(pattern_rows) > 0 and insert_start < len(out):
        # Copy pattern rows below
        for i, row in enumerate(pattern_rows):
            dest_r = insert_start + i
            if dest_r < len(out):
                for c in range(len(out[0])):
                    out[dest_r][c] = row[c]
    return out

