    out = copy_grid(grid)
    # Find first row with a non-4 that appears below the 4-band
    # Look for rows that contain values other than 4 and are not part of the top 4-band
    # In demo, the pattern (rows with 1,2,3,5,7,8) appears below the 4-band and repeats below
    # Find topmost row that has a value != 4 and is below the 4-band
    first_non4_below = None
    for r in range(len(out)):
        has_non4 = False
        for c in range(len(out[0])):
            if out[r][c] != 4:
                has_non4 = True
                break
        if has_non4 and first_non4_below is None:
            # Check if this row is above the 4-band? In demo, row 0-4 are 0s, row 9-9 is 4s, row 10-... are 0s except pattern
            # But row 1 has 5,2 etc. So need to find the row where the 4-band starts
            # Find first row that contains 4
            first4 = None
            for rr in range(len(out)):
                has4 = False
                for cc in range(len(out[0])):
                    if out[rr][cc] == 4:
                        has4 = True
                        break
                if has4:
                    first4 = rr
                    break
            if first4 is not None and r > first4:
                first_non4_below = r
                break
    if first_non4_below is None:
        return out
    # Find last row that contains 4
    last4 = None
    for r in range(len(out) - 1, -1, -1):
        has4 = False
        for c in range(len(out[0])):
            if out[r][c] == 4:
                has4 = True
                break
        if has4:
            last4 = r
            break
    # Collect all rows from first_non4_below to last4-1 that are not all 4s
    pattern_rows = []
    for r in range(first_non4_below, last4):
        all_four = True
        for c in range(len(out[0])):
            if out[r][c] != 4:
                all_four = False
                break
        if not all_four:
            pattern_rows.append(out[r][:])
    # Place pattern below the 4-band starting at last4+1
    insert_start = last4 + 1
    if len(pattern_rows) > 0 and insert_start < len(out):
        for i, row in enumerate(pattern_rows):
            dest_r = insert_start + i
            if dest_r < len(out):
                for c in range(len(out[0])):
                    out[dest_r][c] = row[c]
    return out

