        has4 = False
        for c in range(len(out[0])):
            if out[r][c] == 4:
                has4 = True
                break
        if has4:
            last4 = r
            break
    # Collect all rows from the first row that has a non-4 below row 0 (skip top zeros) up to last4-1 that are not all 4s
    # But only take the first occurrence of the pattern (rows 1-7 in input)
    pattern = []
    taken = False
