    # returns list of components; each component is a list of [row, col, color] pixels
    # connectivity is 4 or 8
    # background is a color; pixels equal to background are ignored
    # grid g is rectangular list of lists of integers 0..9
    n = len(g)
    if n == 0:
        return []
    m = len(g[0])
    visited = [[False for _ in range(m)] for _ in range(n)]
    comps = []

