        stack = [(r, c)]
        comp = []
        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]:
                continue
            visited[cr][cc] = True
            if g[cr][cc] == background:
                continue
            if g[cr][cc] != cur_color:
                # should not happen if background filtered
                return
            comp.append([cr, cc, g[cr][cc]])
            # neighbors depending on connectivity
            if connectivity == 4:
                for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and g[nr][nc] != background:
                        stack.append((nr, nc))
            else:  # 8
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and g[nr][nc] != background:
                            stack.append((nr, nc))
        comps.append(comp)

    for r in range(n):
        for c in range(m):
            if not visited[r][c] and g[r][c] != background:
                dfs(r, c, g[r][c])
    return comps

