def transform(grid):
    out = copy_grid(grid)
    R = len(out)
    C = len(out[0]) if R > 0 else 0
    # find background component that touches border or is largest among border-touching
    border_comps = []
    all_comps = components(out, None, 4)  # use 4-connectivity for consistency
    # collect components that touch any border cell
    for comp in all_comps:
        touches_border = False
        for pixel in comp:
            r, c, col = pixel
            if r == 0 or r == R - 1 or c == 0 or c == C - 1:
                touches_border = True
                break
        if touches_border:
            border_comps.append(comp)
    # if no border component, take largest component among all
    if len(border_comps) == 0:
        all_sizes = [len(comp) for comp in all_comps]
        if all_sizes:
            max_size = max(all_sizes)
            for comp in all_comps:
                if len(comp) == max_size:
                    border_comps.append(comp)
                    break
    # if still none, take first component
    if len(border_comps) == 0 and len(all_comps) > 0:
        border_comps.append(all_comps[0])

    # find the most frequent color among border components (excluding background if known)
    # but background is not given, so use border components' colors
    color_counts = {}
    for comp in border_comps:
        color = comp[0][2]  # first pixel's color
        if color in color_counts:
            color_counts[color] = color_counts[color] + 1
        else:
            color_counts[color] = 1
    # pick color with max count; if tie, pick smallest color
    best_color = None
    best_count = -1
    for col, cnt in color_counts.items():
        if cnt > best_count or (cnt == best_count and col < best_color if best_color is not None else True):
            best_color = col
            best_count = cnt

    # replace all pixels not in any border component with best_color
    # first mark all border component pixels
    border_pixels = set()
    for comp in border_comps:
        for pixel in comp:
            r, c, col = pixel
            border_pixels.add((r, c))

    for r in range(R):
        for c in range(C):
            if (r, c) not in border_pixels:
                out[r][c] = best_color
    return out

