def transform(grid):
    # extract components not equal to background 8
    comps = components(grid, 8, 4)
    # collect all pixel colors present in components (excluding background 8)
    colors_present = []
    for comp in comps:
        for pixel in comp:
            col = pixel[2]
            if col not in colors_present:
                colors_present.append(col)
    # if no component colors (all background), return grid unchanged
    if len(colors_present) == 0:
        return copy_grid(grid)
    # map each present color to a new distinct color from 0..9
    # assign smallest available 0..9 in order of appearance in colors_present
    used = []
    mapping = {}
    avail = list(range(10))
    for col in colors_present:
        found = False
        for v in avail:
            if v not in used:
                mapping[col] = v
                used.append(v)
                avail.remove(v)
                found = True
                break
        if not found:
            # should not happen since at most 10 colors
            # fallback: reuse smallest used
            for v in used:
                mapping[col] = v
                break
    out = copy_grid(grid)
    for comp in comps:
        for pixel in comp:
            r, c, col = pixel
            out[r][c] = mapping[col]
    return out

