    out = helper_expand(out)
    # then fill regions of same color outward
    for col in range(10):
        # collect all pixels of color col that are not 0
        pixels = []
        for r in range(h):
            for c in range(w):
                if out[r][c] == col and col != 0:
                    pixels.append([r, c, col])
